    """Parse INI text."""
    sections: dict[str, dict[str, str]] = {}
    current = None
    key = None
    for lineno, line in enumerate(re.split(r"\r\n|\r|\n", text), 1):
        stripped = line.strip()
        if not stripped or stripped[0] in "#;":
            key = None
            continue
        if key is not None and line[0].isspace():
            current[key] += "\n" + stripped
            continue
        key = None
        if stripped[0] == "[" and stripped[-1] == "]":
            current = sections.setdefault(stripped[1:-1].strip(), {})
            continue
        split = min((i for i in (stripped.find("="), stripped.find(":")) if i >= 0), default=-1)
        if split < 0:
            raise ParseError(lineno, f"invalid line: {stripped!r}")
        if current is None:
            raise ParseError(lineno, "key before any section")
        name = stripped[:split].strip().lower()
        if not name:
            raise ParseError(lineno, "empty key")
        current[name] = stripped[split + 1:].strip()
        key = name
    return _interpolate(sections)


def _interpolate(raw: dict[str, dict[str, str]]) -> dict[str, dict[str, str]]:
    done: dict[tuple[str, str], str] = {}
    active: set[tuple[str, str]] = set()

    def resolve(section: str, key: str) -> str:
        ref = (section, key)
        if ref in done:
            return done[ref]
        if ref in active:
