import re
from dataclasses import dataclass

_NUM = r"(0|[1-9][0-9]*)"
_IDENTS = r"[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*"
_VERSION = re.compile(rf"{_NUM}\.{_NUM}\.{_NUM}(?:-({_IDENTS}))?(?:\+({_IDENTS}))?")
_COMPARATOR = re.compile(r"(\^|~|>=|<=|>|<|=)?(.*)", re.S)


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


def parse(text: str) -> Version:
    """Parse a version string."""
    match = _VERSION.fullmatch(text)
    if not match:
        raise ValueError(f"invalid version: {text!r}")
    major, minor, patch, pre, build = match.groups()
    prerelease = tuple(pre.split(".")) if pre else ()
    if any(len(i) > 1 and i[0] == "0" and _numeric(i) for i in prerelease):
        raise ValueError(f"invalid version: {text!r}")
    return Version(int(major), int(minor), int(patch), prerelease, tuple(build.split(".")) if build else ())


def _numeric(ident: str) -> bool:
    return all("0" <= c <= "9" for c in ident)


def _version(v: str | Version) -> Version:
    return v if isinstance(v, Version) else parse(v)


def _cmp(a, b) -> int:
    return (a > b) - (a < b)


def _compare_prerelease(a: tuple[str, ...], b: tuple[str, ...]) -> int:
    if not a or not b:
        return _cmp(not a, not b)
    for x, y in zip(a, b):
        xn, yn = _numeric(x), _numeric(y)
        if xn and yn:
            c = _cmp(int(x), int(y))
        elif xn or yn:
            c = -1 if xn else 1
        else:
            c = _cmp(x, y)
        if c:
            return c
    return _cmp(len(a), len(b))


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    a, b = _version(a), _version(b)
    core = _cmp((a.major, a.minor, a.patch), (b.major, b.minor, b.patch))
    return core or _compare_prerelease(a.prerelease, b.prerelease)


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    version = _version(version)
    sets = [[_comparator(c) for c in part.split()] for part in range_.split("||")]
    if not all(sets):
        raise ValueError(f"invalid range: {range_!r}")
    return any(_satisfies_set(version, s) for s in sets)


def _comparator(text: str) -> tuple[str, Version]:
    op, rest = _COMPARATOR.fullmatch(text).groups()
    return op or "=", parse(rest)


def _satisfies_set(version: Version, comparators: list[tuple[str, Version]]) -> bool:
    core = (version.major, version.minor, version.patch)
    if version.prerelease and not any(
        v.prerelease and (v.major, v.minor, v.patch) == core for _, v in comparators
    ):
        return False
    return all(_satisfies_comparator(version, op, v) for op, v in comparators)


def _satisfies_comparator(version: Version, op: str, v: Version) -> bool:
    c = compare(version, v)
    if op == "^":
        if v.major:
            upper = Version(v.major + 1, 0, 0)
        elif v.minor:
            upper = Version(0, v.minor + 1, 0)
        else:
            upper = Version(0, 0, v.patch + 1)
        return c >= 0 and compare(version, upper) < 0
    if op == "~":
        return c >= 0 and compare(version, Version(v.major, v.minor + 1, 0)) < 0
    return {"=": c == 0, ">": c > 0, ">=": c >= 0, "<": c < 0, "<=": c <= 0}[op]
