from __future__ import annotations

import re


class ParseError(ValueError):
    def __init__(self, lineno: int, message: str):
        super().__init__(f"line {lineno}: {message}")
        self.lineno = lineno


class InterpolationError(ValueError):
    pass


def parse(text: str) -> dict[str, dict[str, str]]:
    """Parse INI text."""
    sections: dict[str, dict[str, str]] = {}
    current = None
    key = None
    for lineno, line in enumerate(re.split(r"\r\n|\r|\n", text), 1):
        stripped = line.strip()
        if not stripped or stripped[0] in "#;":
            key = None
            continue
        if key is not None and line[0].isspace():
            current[key] += "\n" + stripped
            continue
        key = None
        if stripped[0] == "[" and stripped[-1] == "]":
            current = sections.setdefault(stripped[1:-1].strip(), {})
            continue
        split = min((i for i in (stripped.find("="), stripped.find(":")) if i >= 0), default=-1)
        if split < 0:
            raise ParseError(lineno, f"invalid line: {stripped!r}")
        if current is None:
            raise ParseError(lineno, "key before any section")
        name = stripped[:split].strip().lower()
        if not name:
            raise ParseError(lineno, "empty key")
        current[name] = stripped[split + 1:].strip()
        key = name
    return _interpolate(sections)


def _interpolate(raw: dict[str, dict[str, str]]) -> dict[str, dict[str, str]]:
    done: dict[tuple[str, str], str] = {}
    active: set[tuple[str, str]] = set()

    def resolve(section: str, key: str) -> str:
        ref = (section, key)
        if ref in done:
            return done[ref]
        if ref in active:
            raise InterpolationError(f"cycle at ${{{section}:{key}}}")
        active.add(ref)
        value, out, i = raw[section][key], [], 0
        while True:
            j = value.find("$", i)
            if j < 0:
                out.append(value[i:])
                break
            out.append(value[i:j])
            end = value.find("}", j + 2) if value.startswith("${", j) else -1
            if value.startswith("$$", j):
                out.append("$")
                i = j + 2
            elif end >= 0:
                other, colon, name = value[j + 2:end].rpartition(":")
                other = other.strip() if colon else section
                name = name.strip().lower()
                if other not in raw:
                    raise InterpolationError(f"missing section {other!r} in {value[j:end + 1]}")
                if name not in raw[other]:
                    raise InterpolationError(f"missing key {name!r} in {value[j:end + 1]}")
                out.append(resolve(other, name))
                i = end + 1
            else:
                out.append("$")
                i = j + 1
        active.discard(ref)
        done[ref] = "".join(out)
        return done[ref]

    return {s: {k: resolve(s, k) for k in keys} for s, keys in raw.items()}
